query:
UPDATE site_settings SET description = 'Base price per step for stairs up to 4ft wide. Minimum stair width is 3ft.' WHERE settingKey = 'stair_base_price';
UPDATE site_settings SET description = 'Additional cost per lineal foot for each foot of stair width beyond 4ft.' WHERE settingKey = 'stair_per_lf_over_4ft';
UPDATE site_settings SET description = 'Cost for engineer letter required when framing is selected. Mandatory for second-story decks (8ft+).' WHERE settingKey = 'engineer_letter_cost';
UPDATE site_settings SET description = 'Permit cost when framing is selected. Mandatory for second-story decks (8ft+).' WHERE settingKey = 'permit_cost_framing';
UPDATE site_settings SET description = 'Price per sheet of subfloor material (4x8 = 32 sqft per sheet).' WHERE settingKey = 'subfloor_sheet_price';

